INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > IT-Sicherheit > Bedrohungsszenarien > Digitale Erpressung (Ransomware)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann Ransomware Daten verschlüsseln und den Zugriff darauf blockieren?', 2, '[{"text": "Ja", "correct": true, "because": "Das ist der Hauptmechanismus von Ransomware"}, {"text": "Nein", "correct": false, "because": "Verschlüsselung ist typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist jede Ransomware durch regelmäßige Backups vollständig abwehrbar?', 2, '[{"text": "Nein", "correct": true, "because": "Backups schützen Daten, aber nicht vor erneuter Infektion"}, {"text": "Ja", "correct": false, "because": "Backups sind hilfreich, aber nicht allumfassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss Ransomware immer Lösegeld in Kryptowährung fordern?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Zahlungsmethoden sind möglich, aber selten"}, {"text": "Ja", "correct": false, "because": "Kryptowährung ist üblich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Benutzeraktionen wie das Öffnen von E-Mail-Anhängen Ransomware-Infektionen auslösen?', 2, '[{"text": "Ja", "correct": true, "because": "Phishing ist eine häufige Infektionsquelle"}, {"text": "Nein", "correct": false, "because": "Benutzeraktionen sind oft der Auslöser"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Ransomware ausschließlich auf Unternehmenssysteme beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Privatnutzer können betroffen sein"}, {"text": "Ja", "correct": false, "because": "Ransomware ist breit gefächert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode verwendet Ransomware am häufigsten, um Daten unzugänglich zu machen?', 2, '[{"text": "Verschlüsselung", "correct": true, "because": "Daten werden verschlüsselt und ein Schlüssel gefordert"}, {"text": "Löschung", "correct": false, "because": "Weniger üblich"}, {"text": "Verstecken", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schutzmechanismus ist gegen Ransomware am effektivsten?', 3, '[{"text": "Regelmäßige Backups", "correct": true, "because": "Ermöglicht Datenwiederherstellung ohne Lösegeld"}, {"text": "Starke Passwörter", "correct": false, "because": "Hilfreich, aber nicht primär"}, {"text": "Firewall", "correct": false, "because": "Schützt Netzwerk, nicht direkt Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Weg ist der häufigste Einstiegspunkt für Ransomware?', 2, '[{"text": "Phishing-E-Mails", "correct": true, "because": "Täuschen Nutzer zum Öffnen"}, {"text": "USB-Sticks", "correct": false, "because": "Weniger häufig"}, {"text": "Software-Updates", "correct": false, "because": "Selten genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz hat eine Ransomware-Infektion am ehesten?', 2, '[{"text": "Datenverlust", "correct": true, "because": "Ohne Backup oder Schlüssel sind Daten weg"}, {"text": "Langsamere Systeme", "correct": false, "because": "Nicht primär"}, {"text": "Hardware-Schaden", "correct": false, "because": "Kein physischer Schaden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme sollte nach einer Ransomware-Infektion zuerst ergriffen werden?', 2, '[{"text": "System vom Netzwerk trennen", "correct": true, "because": "Verhindert weitere Ausbreitung"}, {"text": "Lösegeld zahlen", "correct": false, "because": "Nicht empfohlen"}, {"text": "Antivirus starten", "correct": false, "because": "Nach Isolation"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale charakterisieren Ransomware?', 4, '[{"text": "Datenverschlüsselung", "correct": true, "because": "Blockiert Zugriff"}, {"text": "Lösegeldforderung", "correct": true, "because": "Erpressungsmechanismus"}, {"text": "Selbstausbreitung", "correct": true, "because": "Wie Würmer in Netzwerken"}, {"text": "Datenwiederherstellung", "correct": false, "because": "Nicht Ziel der Malware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schutzmaßnahmen helfen gegen Ransomware?', 3, '[{"text": "Regelmäßige Backups", "correct": true, "because": "Ermöglicht Wiederherstellung"}, {"text": "Antivirus-Software", "correct": true, "because": "Erkennt und blockiert"}, {"text": "Schulung der Nutzer", "correct": true, "because": "Verhindert Phishing"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Infektionswege nutzt Ransomware häufig?', 4, '[{"text": "Phishing-E-Mails", "correct": true, "because": "Täuscht Nutzer"}, {"text": "Schwachstellen in Software", "correct": true, "because": "Exploits ausnutzen"}, {"text": "Unsichere Downloads", "correct": true, "because": "Malware versteckt"}, {"text": "Langsame Netzwerke", "correct": false, "because": "Kein Infektionsweg"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann eine Ransomware-Infektion haben?', 3, '[{"text": "Datenverlust", "correct": true, "because": "Ohne Backup unwiederbringlich"}, {"text": "Finanzielle Schäden", "correct": true, "because": "Lösegeld oder Ausfallkosten"}, {"text": "Reputationsverlust", "correct": true, "because": "Vertrauen schwindet"}, {"text": "Verbesserte Sicherheit", "correct": false, "because": "Keine positive Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind nach einer Ransomware-Infektion empfohlen?', 3, '[{"text": "System isolieren", "correct": true, "because": "Stoppt Ausbreitung"}, {"text": "Experten hinzuziehen", "correct": true, "because": "Professionelle Hilfe"}, {"text": "Backups wiederherstellen", "correct": true, "because": "Daten retten"}, {"text": "Lösegeld zahlen", "correct": false, "because": "Nicht empfohlen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ransomware verschlüsselt Daten zur Erpressung. b) Backups machen Ransomware ungefährlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung ja, Backups nicht vollständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Phishing ist ein häufiger Infektionsweg für Ransomware. b) Lösegeld wird immer in Kryptowährung gefordert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Phishing ja, Kryptowährung nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Systeme sollten nach einer Infektion isoliert werden. b) Ransomware betrifft nur Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Isolation ja, auch Privatnutzer betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Antivirus-Software kann Ransomware erkennen. b) Zahlung des Lösegelds garantiert Datenwiederherstellung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erkennung ja, Garantie nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Regelmäßige Backups reduzieren den Schaden durch Ransomware. b) Ransomware kann sich nicht selbst verbreiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups ja, Selbstausbreitung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

